/* The seven figures, Cuban school. One entry per count: both dancers' steps,
 * their words, and the hands, side by side — so motion and text cannot drift. */
(function (G) {
  const { Step: S, Hands: H, Positions: P } = G.Engine;
  const { fwd, back, side, close, replace, pivot, pause, tap, to } = S;
  const c = (lead, you, follow, her, hands) => ({ lead: { step: lead, say: you }, follow: { step: follow, say: her }, hands });

  const OPEN = [H.hold("L", "R", "waist")];
  const CLOSED = [H.hold("L", "R", "shoulder"), H.back()];

  G.FIGURES = [
    {
      id: "guapea", name: "Guapea", en: "The basic",
      sub: "The Cuban basic in open position. Both of you step back on 1 and forward on 5. Everything starts and ends here.",
      start: P.open, end: P.open,
      prep: "Weight on your right foot, left foot free.",
      counts: [
        c(back("L", 0.12), "Left foot back, small, onto the ball of the foot. The joined arms stretch into light tension.",
          back("R", 0.12), "Right foot back.", OPEN),
        c(replace("R"), "Weight forward onto the right foot, in place.",
          replace("L"), "Weight onto the left, in place."),
        c(close("L"), "Left foot closes beside the right.",
          close("R"), "Right foot closes."),
        c(tap("R"), "Pause. Optional tap with the right foot. Decide the next figure here.",
          tap("L"), "Pause, optional tap."),
        c(fwd("R", 0.12, { side: 0.05 }), "Right foot forward, a little diagonal to your right so your feet miss hers. Free hands meet palm to palm.",
          fwd("L", 0.12, { side: 0.05 }), "Left foot forward, slightly to her left.", [...OPEN, H.hold("R", "L", "waist", { palm: true })]),
        c(replace("L"), "Weight back onto the left foot, in place.",
          replace("R"), "Weight onto the right, in place."),
        c(close("R"), "Right foot closes beside the left. Free hands part.",
          close("L"), "Left foot closes.", OPEN),
        c(tap("L"), "Pause. Repeat, or start the next figure on 1.",
          tap("R"), "Pause."),
      ],
      focus: [
        "Rubber band: the arms stretch on 1 and compress on 5. Elastic, never a stiff arm.",
        "Stay on your spot. Guapea does not travel.",
        "Small steps under your body, so you can lead anything from the next 1.",
        "Use the pause on 8 to prepare the next figure, not to rest.",
      ],
    },

    {
      id: "dqs", name: "Dile que sí", en: "Tell her yes",
      sub: "From open position she makes a right turn under your left arm and arrives in closed position.",
      start: P.open, end: P.closed,
      prep: "On the 8 before, lower the joined hands slightly and draw them toward you.",
      counts: [
        c(back("L", 0.1), "Left foot back, a small rock. Draw her toward you with the left hand; she walks in.",
          fwd("R", 0.34), "Right foot forward, walking in.", OPEN),
        c(replace("R"), "Weight onto the right, in place. Raise your left hand above her head.",
          to("L", [0.02, 0.64], { turn: 180 }), "Left foot forward, turning right under the raised hand.", [H.hold("L", "R", "overhead", { over: "her", halo: true })]),
        c(close("L"), "Left foot closes. Draw a small clockwise halo over the middle of her head.",
          to("R", [-0.04, 0.46], { turn: 180 }), "Right foot, finishing the right turn to face him, a little to his right."),
        c(pause(), "Pause. Bring the hand down to shoulder height; your right hand goes onto her left shoulder blade.",
          pause(), "Pause. Left hand onto his right shoulder.", CLOSED),
        c(fwd("R", 0.08), "Right foot forward, small. You are in closed position.",
          back("L", 0.08), "Left foot back."),
        c(replace("L"), "Weight back onto the left, in place.",
          replace("R"), "Weight onto the right, in place."),
        c(close("R"), "Right foot closes.",
          close("L"), "Left foot closes."),
        c(pause(), "Pause. Common next move: dile que no.",
          pause(), "Pause."),
      ],
      focus: [
        "The turn comes from the draw on 1 and the timing of the hand, not from cranking her arm.",
        "The halo is small and centred over her head. A big circle pulls her off balance.",
        "Your feet do a plain basic in place. Do not turn with her.",
        "Right hand onto her back on the pause, then just dance the closed basic on 5.",
      ],
    },

    {
      id: "dqn", name: "Dile que no", en: "Tell her no",
      sub: "The cross-body change of place: you open a path by turning left, she walks across your front, you end facing her.",
      start: P.closed, end: P.open,
      prep: "Closed position, weight on your right foot.",
      counts: [
        c(back("L", 0.1), "Left foot back, a small rock. She steps toward you.",
          fwd("R", 0.1), "Right foot forward.", CLOSED),
        c(replace("R"), "Weight onto the right, in place.",
          replace("L"), "Weight onto the left, in place."),
        c(back("L", 0.12, { turn: -90 }), "Left foot steps back a touch, turning 90° to your left. You open a path across your front; the right hand guides her into it.",
          to("R", [-0.24, 0.1]), "Right foot forward, into the path he opens.", [H.hold("L", "R", "chest"), H.back()]),
        c(pause(), "Pause. You stand side-on to her path.",
          pause(), "Pause."),
        c(back("R", 0.1, { turn: -45 }), "Right foot back as you keep turning left. The right hand sends her past your front, then lets go.",
          to("L", [-0.32, -0.4]), "Left foot forward, crossing in front of him.", [H.hold("L", "R", "waist")]),
        c(replace("L", { turn: -45 }), "Weight onto the left, still turning. The left hand leads her round in a small arc at waist height.",
          to("R", [-0.16, -0.78], { turn: -180 }), "Right foot, pivoting half a turn to her left."),
        c(close("R"), "Right foot closes. You have turned 180° and face her in open position.",
          to("L", [-0.06, -0.95]), "Left foot back, facing him."),
        c(pause(), "Pause. Go into guapea.",
          pause(), "Pause."),
      ],
      focus: [
        "Open the door on 3: get out of her path so she walks straight across, not around you.",
        "The right hand steers on 3 and 5. The left hand takes over on 6 and 7.",
        "Turn your whole body: chest, hips and feet rotate together.",
        "Finish facing her, arm soft and slightly bent, ready for the next 1.",
      ],
    },

    {
      id: "enchufla", name: "Enchufla", en: "Plug it in",
      sub: "You both make a half turn to the left and pass each other; she goes under your left arm and ends beside you.",
      start: P.open, end: P.side,
      prep: "On the 8 before, a small pull down tells her to walk in.",
      counts: [
        c(back("L", 0.1), "Left foot back, a small rock. Gentle pull: she walks toward you.",
          fwd("R", 0.22), "Right foot forward.", OPEN),
        c(replace("R", { turn: -30 }), "Right foot in place, starting to turn left. Raise the left hand to her forehead.",
          to("L", [-0.3, 0.2]), "Left foot forward, passing his left side.", [H.hold("L", "R", "head")]),
        c(fwd("L", 0.14, { turn: -120 }), "Left foot forward as you turn left. The hand goes over her head; you pass left side to left side.",
          to("R", [-0.42, -0.36], { turn: -90 }), "Right foot, turning left under the arm.", [H.hold("L", "R", "overhead", { over: "her" })]),
        c(pivot(-30), "Pause, and finish your half turn on the left foot. You face where you came from.",
          pivot(-90), "Pivots left on the pause, facing where she came from."),
        c(back("R", 0.1), "Right foot back. Lower the hand; she walks forward along your right side.",
          to("L", [-0.45, -0.3]), "Left foot forward.", [H.hold("L", "R", "chest")]),
        c(replace("L"), "Weight onto the left, in place.",
          to("R", [-0.46, -0.22]), "Right foot forward.", OPEN),
        c(close("R"), "Right foot closes. She is beside you, right hip to right hip.",
          to("L", [-0.47, -0.2]), "Left foot, arriving beside him."),
        c(pause(), "Pause. Classic next moves: dile que no, or paséala.",
          pause(), "Pause."),
      ],
      focus: [
        "The turn must be finished by 4. Leading it slowly puts both of you behind the music.",
        "You turn too: both of you make a half turn to the left.",
        "Keep the raised hand straight up over her head, not pulled toward you.",
        "Walk close past each other; a wide path makes the half turn impossible in time.",
      ],
    },

    {
      id: "paseala", name: "Paséala", en: "Walk her",
      sub: "After an enchufla she walks a full circle around you, behind your back, while you stay on your spot.",
      start: P.side, end: P.open,
      prep: "From the end of enchufla: she is on your right, facing the other way. Your left hand holds her right.",
      counts: [
        c(back("L", 0.06), "Left foot back, small. Lead her forward: she walks past your right side toward your back.",
          to("R", [0.42, -0.34], { turn: 30 }), "Right foot forward, starting to curve right.", OPEN),
        c(replace("R"), "Weight onto the right, in place. Lift the left hand over your own head.",
          to("L", [0.05, -0.52], { turn: 60 }), "Left foot forward, curving behind him.", [H.hold("L", "R", "overhead", { over: "him" })]),
        c(close("L"), "Left foot closes. The hand is above your head; she is behind you.",
          to("R", [-0.38, -0.34], { turn: 60 }), "Right foot forward, behind him."),
        c(pause(), "Pause. Keep facing the same way; do not turn around to chase her.",
          pause(), "Pause, keeping the curve."),
        c(fwd("R", 0.06), "Right foot forward, small. Bring the hand down on your left side; she comes round.",
          to("L", [-0.52, 0.12], { turn: 70 }), "Left foot forward, round his left side.", [H.hold("L", "R", "shoulder")]),
        c(replace("L"), "Weight onto the left, in place. The hand leads her out in front of you.",
          to("R", [-0.3, 0.6], { turn: 70 }), "Right foot, turning to face him.", [H.hold("L", "R", "chest")]),
        c(close("R"), "Right foot closes. She faces you in open position.",
          to("L", [0, 0.85], { turn: 70 }), "Left foot, arriving in front of him, facing him.", OPEN),
        c(pause(), "Pause. Continue with guapea or dile que no.",
          pause(), "Pause."),
      ],
      focus: [
        "You are the axis. You stay on your spot and she walks the circle.",
        "The arm goes over your own head, not hers.",
        "Hold loosely so her hand can swivel inside yours as she goes round.",
        "Look for her over your left shoulder as she comes out, to time the lead forward.",
      ],
    },

    {
      id: "sacala", name: "Sácala", en: "Take her out",
      sub: "From closed position she turns right under your left arm and travels out to open position.",
      start: P.closed, end: P.open,
      prep: "Closed position, weight on your right foot.",
      counts: [
        c(back("L", 0.1), "Left foot back, small. A slight turn of your body starts her turning; the left hand starts to rise.",
          fwd("R", 0.1), "Right foot forward.", CLOSED),
        c(replace("R"), "Weight onto the right, in place. Left hand up: she turns right under it, moving away. Release your right hand.",
          fwd("L", 0.3, { turn: 180 }), "Left foot forward, turning right, moving away from him.", [H.hold("L", "R", "overhead", { over: "her", halo: true })]),
        c(side("L", 0.08), "Left foot to your left, making room. A small halo over her head.",
          back("R", 0.32, { turn: 180 }), "Right foot back, finishing the turn to face him."),
        c(pause(), "Pause. Lower the hand to waist height. You are in open position.",
          pause(), "Pause.", OPEN),
        c(fwd("R", 0.08), "Right foot forward, small, like guapea 5.",
          fwd("L", 0.08), "Left foot forward."),
        c(replace("L"), "Weight onto the left, in place.",
          replace("R"), "Weight onto the right, in place."),
        c(close("R"), "Right foot closes. Open position.",
          close("L"), "Left foot closes."),
        c(pause(), "Pause. Go into guapea.",
          pause(), "Pause."),
      ],
      focus: [
        "The start on 1 comes from your body turning slightly, not from shoving with the hand.",
        "Release the hand on her back by count 2.",
        "She travels out; you give her room on 3 but do not follow her.",
        "Lower the arm on 4 so you arrive in a clean open position.",
      ],
    },

    {
      id: "vacilala", name: "Vacílala", en: "Show her off",
      sub: "A traveling, hand-free right turn for her while you change places; you turn right to face her again.",
      start: P.open, end: P.open,
      prep: "On the 8 before, a small pull back prepares her.",
      counts: [
        c(back("L", 0.1), "Left foot back (rock) and draw her toward you: she walks in.",
          to("R", [0.12, 0.62]), "Right foot forward, toward his right side.", OPEN),
        c(replace("R"), "Weight onto the right, in place. Raise the hand, give a small clockwise push to start her right turn, then let go.",
          to("L", [0.26, 0.28], { turn: 180 }), "Left foot, spinning right as she travels.", [H.hold("L", "R", "overhead", { over: "her", halo: true })]),
        c(fwd("L", 0.08, { side: 0.2 }), "Left foot forward-diagonal to your left, out of her path. She passes your right side.",
          to("R", [0.32, -0.16], { turn: 180 }), "Right foot, finishing the spin, traveling past him.", []),
        c(pause(), "Pause. Hands free.",
          pause(), "Pause, still traveling."),
        c(fwd("R", 0.1, { turn: 90 }), "Right foot crosses in front as you start your own right turn.",
          to("L", [0.16, -0.6], { turn: 45 }), "Left foot, curving round."),
        c(fwd("L", 0.08, { turn: 60 }), "Left foot, keep turning right.",
          to("R", [-0.05, -0.86], { turn: 90 }), "Right foot, turning to face him."),
        c(close("R", { turn: 30 }), "Right foot closes. You face her; places exchanged.",
          to("L", [-0.16, -0.92], { turn: 45 }), "Left foot, arriving facing him."),
        c(pause(), "Pause. Offer your left hand low to reconnect.",
          pause(), "Pause, takes his hand.", [H.hold("L", "R", "low")]),
      ],
      focus: [
        "The lead is timing: draw on 1, push on 2. Very little force.",
        "Let go cleanly; do not hang on to her fingers during the spin.",
        "Step out of her path on 3 so she can travel straight.",
        "Your right turn on 5-6-7 must end facing her so you can pick up the hand on 8.",
      ],
    },
  ];
})(typeof window !== "undefined" ? window : globalThis);
